const t={ui:{fig:"Fig. 5",title:"Cerniera con patta",svgLabel:"Un disegno isometrico di come cucire una cerniera con patta in una cucitura: la cucitura cucita fino al segno del fermo in basso, con la fermatura, l'apertura imbastita con il punto più lungo e la cucitura aperta con il ferro; sul lato sotto il margine ripiegato un po' più stretto, la piega accanto ai denti, cucito lungo la piega attraverso il margine e il nastro della zip; la patta stesa sulla zip con la piega sulla linea di cucitura, copre quella cucitura; cucita con il piedino per cerniere lungo la patta e di traverso in basso, lontano dai denti e dal cursore; poi l'imbastitura scucita. Si vede una sola cucitura.",prev:"Passo precedente",dot:(a,i)=>a?`Passo ${a}: ${i}`:i,start:"Passo passo →",next:"Avanti →",overview:"Panoramica",stepOf:(a,i)=>`Passo ${a} di ${i}`,machine:a=>`Macchina: ${a.toLowerCase()}`,inThisStep:"In questo passo",takeApart:"Guarda attraverso la stoffa",putTogether:"Torna alla stoffa",replay:"↻ Ripeti",parts:"Parti",allSteps:"Istruzioni passo passo",endView:"SEZIONE"},stitches:{straight:"Punto dritto",basting:"Punto più lungo"},labels:{rightSides:"dritto contro dritto",markStop:"segna il fermo in basso",toMark:"cucitura fino al segno",backstitch:"fermatura",baste:"imbastisci: punto più lungo",openOut:"apri",wrongUp:"rovescio sopra",pressOpen:"apri la cucitura col ferro",rightUp:"dritto sopra",foldBack:"ribalta la patta",narrower:"un po' più stretto del margine",faceUp:"zip a faccia in su",besideTeeth:"la piega accanto ai denti",alongFold:"cuci lungo la piega",allowanceOnly:"solo margine e nastro",overlapBack:"riporta la patta",covers:"copre la cucitura",belowStop:"di traverso, sotto il fermo",pivot:"gira, ago abbassato",clearTeeth:"lontano da denti e cursore",unpick:"scuci l'imbastitura",oneLine:"si vede una sola cucitura"},steps:[{title:"Cerniera con patta",text:"Un lato della cucitura, la patta, copre la zip: il suo bordo piegato sta sulla linea di cucitura, e si vede una sola cucitura, lungo questo lato e di traverso in basso. Tocca per guardare attraverso la stoffa."},{title:"Dritto contro dritto",text:"Metti i due pezzi dritto contro dritto. Appoggia la zip lungo la linea di cucitura e segna dov'è il suo fermo in basso: lì finisce l'apertura per la zip.",details:["Prima rifinisci i bordi della cucitura, così non si sfilacciano.","Metti i due pezzi dritto contro dritto, i bordi pari, e fissali con le clip.","Appoggia la zip lungo la linea di cucitura e segna la linea di cucitura al suo fermo in basso: lì finisce l'apertura per la zip."]},{title:"La cucitura fino al segno",text:"Cuci la cucitura con il punto normale fino al segno e fai lì la fermatura, così la cucitura tiene dove finisce la zip.",details:["Cuci la cucitura con il punto normale, sulla linea di cucitura, fino al segno.","Fai la fermatura al segno: dove finisce la zip la cucitura non deve aprirsi."]},{title:"Imbastisci l'apertura",text:"Imposta il punto più lungo e chiudi l'apertura sulla stessa linea di cucitura, tra il segno e il bordo superiore. Questa imbastitura alla fine si scuce.",details:["Imposta sulla macchina il punto più lungo: è un'imbastitura, dopo la scuci.","Chiudi l'apertura sulla stessa linea di cucitura, tra il segno e il bordo superiore.","L'imbastitura tiene i due lati dell'apertura sulla linea di cucitura mentre cuci la zip."]},{title:"Apri la cucitura col ferro",text:"Apri i pezzi, girali con il rovescio sopra e apri i margini di cucitura con il ferro, uno per lato, lungo tutta la cucitura.",details:["Apri i pezzi e girali con il rovescio sopra.","Apri i margini di cucitura con il ferro, uno per lato, lungo tutta la cucitura, anche la parte imbastita."]},{title:"Ribalta la patta",text:"Gira il lavoro con il dritto sopra. Un lato dell'apertura, la patta, poi coprirà la zip; l'altro, il lato sotto, le sta sotto. Ribalta la patta perché non dia fastidio: l'imbastitura la tiene sulla linea di cucitura.",details:["Gira il lavoro con il dritto sopra.","Scegli la patta: il lato che coprirà la zip. L'altro lato è il lato sotto.","Ribalta la patta sul lato sotto, così non finisce nella cucitura seguente."]},{title:"Il lato sotto e la zip",text:"Sul lato sotto ripiega il margine un po' più stretto del margine di cucitura, così la piega cade appena oltre la linea di cucitura. Infila sotto la zip a faccia in su, la piega accanto ai denti, e appunta.",details:["Ripiega il margine del lato sotto un po' più stretto del margine di cucitura e stira: la piega cade appena oltre la linea di cucitura.","Infila la zip a faccia in su sotto la piega, i denti proprio accanto, il fermo in basso al segno.","Appunta la piega al nastro della zip."]},{title:"Cuci lungo la piega",text:"Con il piedino per cerniere cuci vicinissimo alla piega, solo attraverso il margine e il nastro della zip, per tutta la lunghezza della zip, ma mai sopra il fermo in basso.",details:["Monta il piedino per cerniere: con lui l'ago cuce vicino alla zip.","Cuci vicinissimo alla piega, solo attraverso il margine e il nastro della zip: la patta resta ribaltata.","Cuci per tutta la lunghezza della zip, ma mai sopra il fermo in basso."]},{title:"La patta sulla zip",text:"Riporta la patta sopra la zip, il suo bordo piegato sulla linea di cucitura: copre i denti e la cucitura lungo la piega. Appuntala attraverso tutti gli strati.",details:["Riporta la patta sopra la zip: l'imbastitura tiene il suo bordo piegato sulla linea di cucitura.","La patta copre i denti e la cucitura lungo la piega del lato sotto.","Appunta la patta al nastro della zip sotto, attraverso tutti gli strati."]},{title:"Cuci la patta",text:"Con il piedino per cerniere cuci lungo la patta e di traverso in basso, sotto il fermo, girando all'angolo con l'ago abbassato, attraverso tutti gli strati. Resta abbastanza lontano da evitare i denti e il cursore.",details:["Cuci lungo la patta, sempre alla stessa distanza dal suo bordo piegato: abbastanza lontano da evitare i denti e il cursore.","Cuci di traverso in basso, sotto il fermo: mai sopra il fermo.","All'angolo fermati con l'ago abbassato nella stoffa, alza il piedino, gira il lavoro e continua."]},{title:"Scuci l'imbastitura",text:"Scuci l'imbastitura sopra la zip e stira. La patta resta sopra la zip, e si vede una sola cucitura.",details:["Scuci i punti dell'imbastitura sopra la zip.","Stira sul dritto: la patta copre la zip, si vede solo la sua cucitura."]}],legend:[{title:"Stoffa",text:"due pezzi uniti da una cucitura · il bordo piegato della patta sulla linea di cucitura"},{title:"Cucitura della zip",text:"una sola: lungo la patta e di traverso sotto il fermo"},{title:"Cucitura",text:"sotto la zip, con la fermatura al segno"},{title:"Zip",text:"sotto la patta, cucita al lato sotto lungo la sua piega"}]};export{t as default};
